//! The icon of each file and folder according to Material Icon Theme, with the same rules as VS Code:
//! exact name, then the longest extension, otherwise the generic one.
//!
//! The table (`icons.tsv`) is generated by `scripts/generate-icons.mjs`; here it is only looked up.

use std::collections::HashMap;
use std::sync::LazyLock;

use ratatui::style::Color;

pub struct Icon {
    pub glyph: char,
    pub color: Color,
}

struct Table {
    icons: HashMap<&'static str, Icon>,
    files: HashMap<&'static str, &'static str>,
    extensions: HashMap<&'static str, &'static str>,
    folders: HashMap<&'static str, (&'static str, &'static str)>,
    defaults: HashMap<&'static str, &'static str>,
}

// The table is embedded in the binary; if it is malformed that is a generator bug, not a user error.
static TABLE: LazyLock<Table> = LazyLock::new(|| {
    let mut t = Table {
        icons: HashMap::new(),
        files: HashMap::new(),
        extensions: HashMap::new(),
        folders: HashMap::new(),
        defaults: HashMap::new(),
    };
    for line in include_str!("icons.tsv").lines().filter(|l| !l.starts_with('#')) {
        let fields: Vec<&str> = line.split('\t').collect();
        match fields.as_slice() {
            ["I", name, color, glyph] => {
                let rgb = u32::from_str_radix(&color[1..], 16).expect("icons.tsv: malformed colour");
                let code = u32::from_str_radix(glyph, 16).expect("icons.tsv: malformed glyph");
                let icon = Icon {
                    glyph: char::from_u32(code).expect("icons.tsv: glyph outside Unicode"),
                    color: Color::Rgb((rgb >> 16) as u8, (rgb >> 8) as u8, rgb as u8),
                };
                t.icons.insert(name, icon);
            }
            ["F", name, icon] => drop(t.files.insert(name, icon)),
            ["E", ext, icon] => drop(t.extensions.insert(ext, icon)),
            ["D", name, closed, open] => drop(t.folders.insert(name, (closed, open))),
            ["X", key, icon] => drop(t.defaults.insert(key, icon)),
            _ => panic!("icons.tsv: unknown line: {line}"),
        }
    }
    t
});

fn icon(name: &str) -> &'static Icon {
    let t = &*TABLE;
    t.icons.get(name).unwrap_or_else(|| &t.icons[t.defaults["file"]])
}

pub fn for_file(name: &str) -> &'static Icon {
    let t = &*TABLE;
    let name = name.to_lowercase();
    if let Some(i) = t.files.get(name.as_str()) {
        return icon(i);
    }
    // From the longest extension to the shortest: «x.test.tsx» tries «test.tsx» before «tsx».
    for (i, _) in name.match_indices('.') {
        if let Some(ext_icon) = t.extensions.get(&name[i + 1..]) {
            return icon(ext_icon);
        }
    }
    icon(t.defaults["file"])
}

pub fn for_folder(name: &str, open: bool, root: bool) -> &'static Icon {
    let t = &*TABLE;
    let key = match (root, open) {
        (true, false) => t.defaults["rootFolder"],
        (true, true) => t.defaults["rootFolderExpanded"],
        (false, _) => match t.folders.get(name.to_lowercase().as_str()) {
            Some(&(closed, opened)) => {
                if open {
                    opened
                } else {
                    closed
                }
            }
            None => t.defaults[if open { "folderExpanded" } else { "folder" }],
        },
    };
    icon(key)
}
